/* =========================================================
   دليل الاستخدام (Help Guide) — نافذة ثابتة بالعربي/الإنجليزي، أقسام قابلة للطي
   ========================================================= */
let helpLang = 'en' // أ-١٢-٢: لغة الواجهة;
let helpOpenIndex = -1; let helpExpanded = false; // أ-١٢-٢: المستوى الثاني مطوي افتراضيًّا; // القسم المفتوح افتراضيًا (الأول)

const HELP_CONTENT = { // أ-١٢-٢ (نص المالك v2 المعتمد ١٦ سبتمبر — على الوضع النهائي): المستوى الأول شاشة واحدة، الثاني أقسام مطوية
  en: {
    title: 'MyPickz — one place for your places.', closeLabel: 'Close', readMore: 'Read more', readLess: 'Read less', gotIt: 'Got it — sign in',
    intro: {
      def: "One platform for four things: reaching your favorite places anywhere in the world, planning your trips, keeping your personal addresses, and exploring — and saving — other users' places and trips.",
      feats: 'Categorized on two levels · Nearby, sorted by distance from where you are · A day route with your own minutes · Export as a card with QR · Share with one person by name or a saved group · Import your Google Maps lists in one file · Follow curators · Your addresses, private.', /* r76 (دراسة التوافق · ت٢): ما لم يُبنَ بعد موسوم */
      dests: [
        ['Places', 'your favorite places, city by city, in categories. Paste a Maps link and the place fills itself in.'],
        ['Trips', 'a plan drafted for you by day and period, then a day route with the minutes you enter.'],
        ['Curators', 'active members whose favorites you may like: when to go, what to order, where to sit.'],
        ['Community', "other users' public lists and trips, by city and category."],
        ['Addresses', 'your personal addresses: home, work, family — never shared, never public.'] ],
      everywhere: '<b>Bookmark</b> what you like · <b>Save</b> a place or trip to your own world · <b>Export</b> a card or a message · <b>Share</b> a list, a trip, or a curator — publicly or with one person by name.',
      start: '<b>Start fast:</b> create your account, add a city, then paste your first Maps link — or import your saved Google Maps lists in one file.' },
    sections: [
      { id: 'places', h: 'Places', b: "Every place lives in one city and one sub-category (the tree is ours: cafés, dishes, cuisines, shopping, parks, squares, waterfronts, landmarks, family, stay, transport). Add a place from a Maps link: name and area fill in, the category is suggested, and the pin is placed for you — correct it with one drag. If a save fails (no connection), a sheet asks Retry or Discard; a change you keep shows <b>Unsaved</b> next to My places until it saves (r100-أ). While a save or delete is running its button is disabled and a second tap is ignored — one tap, one change (r100-ب). Text fields have limits (name 120 · note 2,000 · nickname 24): a counter appears as you near the limit, and Save asks you to shorten rather than cutting your text (r100-ج). When something can't load or save, the message says why in plain words — check your connection, you don't have access, try again — and what was on screen stays; if the free daily quota runs out you'll see <b>MyPickz is busy today — back at 11:00 Riyadh</b> (r100-د). A private daily backup of all data is taken at 11:30 Riyadh (r100-و). Saving writes only the categories you touched, and keeps places added from another device. Your list shows sections you have content in, with counts. Filter by category, then sub-category. Switch <b>☰ List · 🗺 Map</b>; <b>📍 Nearby</b> (beside Day plan) sorts this city's places by straight-line distance from where you are — ≤ 1 km · ≤ 3 km · Any — with a <i>Go</i> button in your navigation app. Your location is asked when you tap and never stored.<br><b>Adding a place (r93):</b> the window starts with the <b>Google Maps link</b> — paste what Maps shared (or tap 📋 Paste) and the name and area fill in; then <b>Plus code</b> (from under the address in Maps: one exact pin, and the area reads from it), then Name, then the category with <i>Fine dining · ⭐ Top place · Outside the city</i>. <b>Outside the city</b> marks a nearby town kept under this city; when a city has such towns, a row <b>Places outside …: Estepona · N</b> appears above the categories — tap a town to see its places only (list and map), tap it again for the whole city; the town chip on a card opens it too. <b>⚙</b> at the end of the row manages the city: <i>Merge into another city</i>, <i>Split out a town</i>, move one place from Edit, <i>🗑 beside a town</i> (r97: removes that folded town and its places; the rest of the city stays), and <i>Undo</i>. <b>Duplicates (r97):</b> places you have twice show as a folded row <i>▸ Duplicates · N</i> in the box above the list — <i>Same Google place</i> or <i>Same spot</i>; tap a name to open its card, then <i>Keep this</i> on the one to keep (the rest merge into it; Undo sits on the row). <b>One spot, one place (r96):</b> saving or pinning a place at a spot you already have asks <i>Keep both · Keep mine · Replace mine</i>; in a batch such rows are held with <i>Keep both · Drop this row</i>. <b>Areas (r96):</b> the area is read from the pin by one rule for every path (Paris → 7e arr. · Vienna → district · a village before its hamlet, the city or canton never); after this update a one-time <i>Re-read N pins</i> banner refreshes the areas you already have. With a town chip on, the box above the list (without a category / old category) shows that town only, and the chip says how many are in the box. When a city holds three places or more and no day plan yet, one line above My places offers to plan a day; it goes away with the first plan (r101-ب). Saved day plans of this city show as chips under the button row — 🏙 in the city, 🚞 day trip, <i>· draft</i> for an unfinished one — and open with one tap (r102-د). <b>They follow the list</b> (r103): when a city list is public, its day plans are public with it; when it is shared by name, they are shared with the same people — no switch to set. Viewers see them as chips on your city page and open them read-only: stops in order, category, note and distances; the app does not show them your start point, times or leg minutes (those fields still travel inside the plan document, as with any public trip). Drafts never leave you; a plan follows the list when you save it. Day plans never appear in the trips feeds, and deleting or merging a city makes its plans private again. Public and shared, under the hood (r104): a city list is one index document plus one document per sub-category, and each of those carries its own public/shared mark, so a viewer can read only the sub-categories that carry it. Pressing 🌐 or sharing by name now stamps every sub-category in the same write, and opening your own list once repairs any sub-category whose mark fell out of step (Diag shows <i>visibility repaired</i>). A viewer who meets a list that claims places but shows none sees <i>Couldn't read this list's places</i> rather than <i>No active places</i>. <b>Names and pins (r107)</b>: a short Plus code (PXCR+2C New York) is read around the town it names. The name is matched by its main name first — a side-name that only a far-away town carries is never trusted on its own: when the name is unclear you are asked <i>Which …?</i> or <i>Where is …?</i> instead of getting a pin in the wrong place. A pin that would land far from this city is not saved quietly either: <i>That pin is … km from …</i> lets you go back and fix it, or keep it as outside the city. <b>⚙ City › Far pins</b> lists pins saved far from the city that are not marked outside, shows where the same code lands near the city, and moves them (one or all, with Undo). <b>Not fully visible yet (r109)</b>: a dot on 🌐 means some sub-categories of this list still carry a different public/shared mark than the list itself (a repair could not be written — offline, refused, or the account is suspended). Tap 🌐 and the app tries the repair again; it does not switch public on or off while the dot is there. Saving the whole list (or switching public / sharing) writes the mark on every sub-category and clears the dot too. Diagnostics shows one line for every visibility event: <i>VIS · city · public|private · shared N · what happened</i>. <b>Community reads (r109)</b>: the market is read once and kept for the visit — going back, changing tab or returning within ten minutes reads nothing; the line under the filters says when it was read, and ↻ reads it again now. What you do yourself — publish or hide, bookmark, save, copy — is read from the server right after, so your own change never waits; view counts and other people\'s changes arrive with the next read. <b>Checked when opened (r109)</b>: a trip or a list kept in memory is checked with one read every time you open it — if its owner made it private, stopped sharing it, or the account was suspended, it is gone at once (<i>This list is no longer available</i>). Suspending an account hides every list, every sub-category under it and every trip; lifting it brings each one back exactly as it was." },
      { id: 'trips', h: 'Trips', b: "Build a trip in two steps: the city, the days and the places you pick — optionally arrival, departure, where you stay and what you take when it is too far to walk — then MyPickz drafts each day in four periods: morning, noon, afternoon, evening, with alternatives when several places are of the same kind and a <i>No day yet</i> tray for what did not fit. <i>Move</i> anything, switch between Calm, Balanced and Dense, undo, then approve. Prefer to place them yourself? <i>Arrange it myself</i> keeps every place in the tray and the grid asks you for each one in turn; <i>Auto-fill the rest</i> places what is left. The ▲ ▼ arrows beside a stop's number reorder it within its period; moving into another period that already has stops asks where in the order; <i>Add again…</i> adds a second visit to the same place (r105: the same name in both paths). Tap <i>Trip</i> on any place card and it lands in its best slot — or in the tray. <b>Day route</b>: open an approved trip, pick a day, set when you leave and by when you want to be back; each leg shows its rough distance and a mode (walk, metro and transit, car — the default follows the distance), and <i>Navigate</i> opens your app in that mode. Write the minutes your app shows — MyPickz never estimates them — and the times of the day follow; a leg without minutes keeps the day <i>incomplete</i>, and a late return is flagged.<br><b>Day plan — one path, one difference</b> (r106): a one-day plan that lives in Places, not in My trips. The two paths share everything — the two doors that add stops, Start from and the return leg, Options, Add again, the leg modes, the place card, the same Day route after saving — and differ in one thing you choose on the first screen: <b>who orders the stops</b>. <b>In the city</b>: MyPickz by periods (morning, midday, afternoon, evening, with Options when two places are of the same kind) or <i>My order</i>. <b>Day trip</b>: <i>My order</i> (the order you add them in, ▲ ▼) or <i>Nearest first</i> from your start point (each added stop slots in nearest-first; move one by hand and the order is yours again). Two kinds, in detail — <b>In the city</b> (your places in the usual rhythm) and <b>Day trip</b> (a linear route out of the city: villages, peaks, lakes, stations — two doors add the stops: <b>Add from My places</b> (your saved places here and nearby, shown with their category and note) and <b>Add a place not in My places</b> (typed, or from a Maps link — it stays inside this day); each leg with its transport: train, boat, cable car, cogwheel, bus, walk, car — notes, an optional stop, a fixed time; <b>Save this day</b> wakes up with the first stop, and nothing is written before a stop or a name, r101-ب). In the picker, <b>Stay</b> and <b>Transportation</b> places are pickable like any other (a resort with a café or golf, a station, a car park: 60 and 15 minutes by default) (r102-ب). In a saved plan, tapping a stop's name opens its place card — category, area, note, Google Maps — and the line under the name shows category and area; a stop's pin follows the place's current pin in your list, so correcting a pin corrects the distances (r102-ج). Give it a <b>Trip name</b>; open it from <i>Day plan ▸ Saved</i> or from its chip in Places; <b>⧉ Copy into a trip</b> copies the day into one of your trips as a new day or in place of one, with Undo. <b>Nearby cities</b> (r101-أ): when you pick from My places, a row of chips names your other cities within about an hour and a half by car one way — <i>+ Gstaad · ~1 h</i>; tap one and its places join the list under its name, and each picked place keeps the city it belongs to. The time is an estimate from the straight-line distance, not a route. Both paths (r105): Start from in a day plan lists Transportation first (station, parking), then Stay, then the rest of your pinned places, and an unpinned place is listed greyed with the reason (the multi-day Where you stay picker greys them too). Options in Day route after saving: a stop with alternatives shows Option 1 ✓ and Option 2… — tap one to make it the real stop; the legs are recomputed for it, but minutes you typed for the old option are not carried, so re-enter them. Add again: the same place once more (in the city from the Move sheet; in a day trip from the stop chips, at the end of the route). In the city, ✎ Not in My places next to ＋ Places adds a typed stop that lands in No day yet and asks where. Viewers of a public or shared day plan see each leg in the mode you chose, with its note, and open the place card from a stop's name. <b>Two day shapes (r107)</b>: an in-city day is laid out in periods; a day-trip day keeps its stops in <i>your order</i>. Every step now knows both: Setup and Done keeps a day trip's stops, start point and order; <i>Trip</i> on a place card adds it as the last stop of a day trip and says so; a day plan copied into a longer trip keeps its day when you change days or rhythm, opens with the same stop editor (day chips on top, <i>Move</i> on each stop), and the Move sheet shows it as one wide cell — the place joins its route. An emptied day-trip day can be turned back with <i>Make it an in-city day</i>. Copies made with <i>Add again</i> and your alerts survive a rebuild. If a step would ever drop a place or redraw such a day without asking, nothing is saved, the plan returns as you last saved it and a sheet says <i>Kept as it was</i>. <b>Editing is a session (r108)</b>: nothing is written while you edit. A plan that is not approved yet ends with <i>Cancel · Save as draft · Approve</i>; an approved one with <i>Cancel · Done</i>. Leaving with changes asks <i>Discard your changes?</i> and, if you discard, the plan is exactly as it was. If the app closes in the middle, your edit is kept on this device only and the next visit asks <i>Restore your unsaved edit?</i>. There is one door to add: <i>＋ Add places</i> — tick places in My places and nearby cities, or open <i>A place not in My places</i> inside it — and a note then says where each one landed (the period, an alternative, the stop number, or <i>No day yet</i>). <i>Setup</i> is a step inside the session (<i>Apply</i> brings you back to the plan), and a saved trip has one way in: <i>✏️ Edit</i>. Inside a session the guard does not throw your work away: a save that would drop a place you did not remove is refused with <i>Not saved</i> and the edit stays open. Things done outside the editor stay immediate: <i>Trip</i> on a place card, copying a day plan, and Undo of the last of these." },
      { id: 'curators', h: 'Curators', b: "A curator's world is a showcase of their favorites, on top of their ordinary lists: cards with their own headings — <i>best time</i>, <i>what to order</i>, <i>where to sit</i> — a city card they keep updating, and <i>latest experiences</i>. Follow a curator to see what's new from them first. Browse their places and trips as they see them — read-only. Curators are invited by MyPickz or apply from their account; the badge means a space, not a rating." },
      { id: 'community', h: 'Community', b: "Other users' public lists and trips, by city — and who saved what. Filter by category and sub-category; open a list and save a place to your own — it keeps its source. Your list is private until you make it public; sharing by name with one person stays between you two." },
      { id: 'addresses', h: 'Addresses', b: 'Home, work, family, friends, clinics — your private book. Only you read it; nothing here ever appears in lists, trips, or the community. Paste from Maps, or type an address.' },
      { id: 'cards', h: 'Cards & sharing', b: "Any place, list, trip, or curator card can be exported as an image in the app's style — Arabic or English — with a QR code that opens it in MyPickz. Long lists split into several cards. Send it anywhere; whoever opens it can save what they like." },
      { id: 'import', h: 'Import', b: '<b>Import your Google Maps lists</b><br>1. Open <b>takeout.google.com</b>, sign in with the Google account you use in Maps → <i>Deselect all</i> → tick <b>two</b> items: <b>Saved</b> (your lists) and <b>Maps (your places)</b> → <i>Next step</i> → <i>Create export</i>.<br>2. Google emails you “Your Google data is ready” (minutes, up to a few hours) → <i>Download your files</i> → the .zip lands in Files → Downloads (iPhone) or Downloads (Android).<br>3. Here: ☰ → Import → choose the .zip (no need to unzip).<br>4. Your places are sorted into cities <b>on your device</b> — nothing is uploaded, nothing is read from Google. You see them as a tree: country → city → smaller towns, and decide with one tap whether a small town stays its own city or goes under the big city next door (as its area). A new city with only 1–2 places is tucked under the city next door by default when it is within 20 km (the row says so, with undo), or left unticked for you to decide; towns you saved as places (“Bled”, “Biarritz”) are counted as destinations and not imported unless you say so. Tell us once what each list is mostly about (optional).<br>5. Open a city → the box above the list shows <b>N not pinned yet ›</b> until every place has a pin (r98b: the two status lines are gone — the file count lives in ⓘ Diag): everything from your file is on your list with its Google link; a pin is needed only to put a place in a day plan or see it on your map. MyPickz looks each place up in our map data (by name — even when your list link points a few km away) and sorts it into its category. Then three steps: <b>1 · Pin the matches</b> — one tap for <b>Strong</b> (exact name) and <b>Likely</b> (check the ↔ names; 🗑 anything old or unimportant, with Undo). <b>2 · Pick the right name</b> — for a place with look-alikes, tap the right one (each shows its address). <b>3 · Pin from Google Maps</b> — for the rest, tap <b>Pin</b> on the card: open the place in Google Maps, swipe its card up and under the address tap <b>Plus code</b> (something like <b>GV74+C3 London</b> — it says Copied), come back and tap <b>Paste</b>: one exact pin, decoded on your device, no Google call. Every pinned card shows its own Plus code under the address, so checking a pin is comparing two lines — same code, same spot. A short code (6 characters) is only exact near its town, so it is decoded around a reference: the town name Google copies with it (<b>8FR9+2V Interlaken</b>), else the town when the place is marked Outside the city, else this city. If the result lands more than 40 km from that reference nothing is saved and the message asks for the code with its town name or the full code; this catches a wrong reference only when both candidate spots are far, so for a far place always keep the town name with the code (r102-أ). Or keep them on your list without a pin (<b>Not pinned yet</b> lists them and can save them as a file). What it can’t tell stays in the box for you — including places outside the content guidelines (bars, nightlife, alcohol, hookah, gambling), which are marked and never sorted.<br>6. Changed your mind? <b>Undo last import</b> — in ⚙ City (<i>Pins &amp; import</i>) or ☰ → Import — removes what the import added and keeps anything you worked on — pinned, edited, moved, or put in a trip. Choosing the same file again later applies the choices you made and skips places you removed by hand. A <b>Receipt</b> lists what came in. If the app closed mid-way, <b>Resume</b> finishes the cities that were left.<br><b>What happens to each place</b><br>· <b>Already in your list</b> → skipped, nothing changes. <b>Same name as an older place of yours</b> (one row, one place) → no twin: the older place gains the map id and the long link, keeps its pin. <b>Looks similar</b> to one you have → kept, marked so you decide.<br>· <b>In a city you don\'t have yet</b> → the city is created for you.<br>· <b>In a city we don\'t cover yet</b> → counted and kept out; when its country is known it <b>waits</b> (name and link only, no location) until you add a city there — then “Place them now” brings it in.<br><b>Privacy:</b> your Takeout file is read on your device only and never sent. Each place keeps the file’s location in its own link so we can match it on our map; pins come only from our map data, never from the file.<br><b>After the import:</b> ⚙ in the Places row — <i>Merge into another city</i> (its places keep their categories, tagged as a town outside the bigger city), <i>Split out a town</i> (a new city from our list or from its pins), move one place from Edit, <i>🗑 beside a town</i> (r97: remove a folded town with its places), <i>Undo</i>, and under <i>Pins &amp; import</i> (r98b) <i>Re-read areas from pins</i> and <i>Undo last import</i> — the Pins panel on the map shows only while something is left to pin. The same place twice shows as <i>▸ Duplicates · N</i> in the box above the list (r97) — tap a name for its card, keep one, the rest merge into it. During a batch, a row at a spot you already have is held — <i>Keep both</i> or <i>Drop this row</i>.' },
      { id: 'privacy', h: 'Your data & privacy', b: 'Your places are yours: download everything as an open file any time, import it back, and delete your account with all its traces. Location is used only when you tap <i>Nearby</i> and is never stored. Following is public to the person you follow. We use open map data with attribution. From a Google Maps link we read only the place name and address to find it in our own data — never its coordinates; the link stays the door. A place saved without a link opens as a search in Google Maps by its name, area, city and country. Your Takeout file is read on your device only and never sent; each place keeps the file’s location in its own link for matching, and pins come only from our map data. MyPickz is not affiliated with Google.' },
      { id: 'howto', h: 'How to copy a link & export your lists', b: '<b>A place link:</b> open the place in Google Maps → Share → Copy → back in MyPickz: ＋ Add place → Paste from Maps.<br><b>Your saved lists:</b> Google Takeout → Deselect all → tick "Saved" and "Maps (your places)" → Create export → download the .zip from Google’s email → MyPickz → ☰ → Import.<br><b>On Android:</b> from Google Maps, Share → MyPickz directly <span class="soon-tag">Soon</span>.' },
      { id: 'settings', h: 'Settings', b: 'Home screen (auto or your choice) · my cities · export language · account.' },
      { id: 'home', h: 'Adding MyPickz to your Home Screen or Desktop, on mobile or computer', b: '1. Open the site in your browser (Safari or others)<br>2. Tap the Share button on mobile, or the options menu on desktop<br>3. Choose "Add to Home Screen" (mobile) or "Create Shortcut" (desktop)<br>4. Now you can open MyPickz with one tap, like any other app' }
    ]
  },
  ar: {
    title: 'MyPickz — مكان واحد لأماكنك.', closeLabel: 'إغلاق', readMore: 'المزيد', readLess: 'أقل', gotIt: 'فهمت — دخول',
    intro: {
      def: 'منصة واحدة لأربعة أشياء: الوصول إلى أماكنك المفضلة بأي مكان في العالم، تخطيط رحلاتك، حفظ عناوينك الخاصة، واستكشاف — وحفظ — أماكن المستخدمين الآخرين ورحلاتهم.',
      feats: 'مصنَّفة بمستويين · القريب مني مرتَّبًا بالبعد عن موضعك · مسار يوم بدقائقك أنت · تصدير بطاقةً بـQR · مشاركة مع شخص بعينه بالاسم أو مع مجموعة محفوظة · استيراد قوائمك من خرائط جوجل بملف واحد · متابعة المنتقين · عناوينك خاصة.',
      dests: [
        ['الأماكن', 'أماكنك المفضلة مدينةً مدينة بالتصنيفات؛ الصق رابط الخرائط فيُملأ المكان بنفسه.'],
        ['الرحلات', 'خطة تُرسم لك بالأيام والفترات، ثم مسار يوم بالدقائق التي تكتبها أنت.'],
        ['المنتقون', 'أعضاء نشطون قد تعجبك مفضلاتهم: متى تذهب وماذا تطلب وأين تجلس.'],
        ['المجتمع', 'قوائم المستخدمين الآخرين ورحلاتهم العامة بالمدينة والتصنيف.'],
        ['العناوين', 'عناوينك الخاصة: البيت والعمل والأهل — لا تُشارَك ولا تُنشر أبدًا.'] ],
      everywhere: '<b>تمييز</b> لما تحب · <b>حفظ</b> لمكان أو رحلة إلى عالمك · <b>تصدير</b> بطاقةً أو رسالة · <b>مشاركة</b> قائمة أو رحلة أو منتقٍ — علنًا أو مع شخص بعينه بالاسم.',
      start: '<b>ابدأ بسرعة:</b> أنشئ حسابك، أضف مدينة، ثم الصق أول رابط — أو استورد قوائمك المحفوظة بخرائط جوجل بملف واحد.' },
    sections: [
      { id: 'places', h: 'الأماكن', b: 'كل مكان بمدينة واحدة وفرعي واحد (الشجرة لنا: مقاهٍ · وجبات · مطابخ · تسوّق · حدائق · ساحات · واجهات بحرية · معالم · عائلة · إقامة · تنقل). أضف مكانًا من رابط الخرائط: يُملأ الاسم والمنطقة، ويُقترح التصنيف، ويُوضع الدبوس لك — صحّحه بسحبة. وإن فشل الحفظ (بلا اتصال) تسألك ورقة Retry أو Discard؛ والتعديل الذي تُبقيه يظهر <b>Unsaved</b> بجانب My places حتى يُحفظ (r100-أ). وأثناء الحفظ أو الحذف يتعطّل الزر وتُتجاهل النقرة الثانية — نقرة واحدة، تغيير واحد (r100-ب). وللخانات حدود (الاسم ١٢٠ · الملاحظة ٢٠٠٠ · الاسم المستعار ٢٤): يظهر عدّاد حين تقترب من الحد، وSave يطلب الاختصار بدل أن يقصّ نصك (r100-ج). وحين يتعذّر تحميل شيء أو حفظه تقول الرسالة السبب بكلمات واضحة — تحقق من الاتصال · لا صلاحية · حاول مجددًا — ويبقى ما على الشاشة؛ وإن نفدت الحصة اليومية المجانية ترى <b>MyPickz is busy today — back at 11:00 Riyadh</b> (r100-د). ونسخة احتياطية خاصة من كل البيانات تُؤخذ يوميًا ١١:٣٠ الرياض (r100-و). الحفظ يكتب التصنيفات التي مسستها فقط ويُبقي ما أضافه جهاز آخر. قائمتك تعرض الأقسام التي لك فيها محتوى بعدّاداتها. صفِّ بالتصنيف ثم الفرعي. بدّل العرض: ☰ قائمة · 🗺 خريطة؛ و«📍 Nearby» (بجوار Day plan) يرتّب أماكن المدينة بالبعد المستقيم عن موضعك — ≤ 1 km · ≤ 3 km · Any — بزر <i>Go</i> يفتح تطبيق الملاحة الذي اخترته. موقعك يُطلب عند النقر ولا يُخزَّن.<br><b>إضافة مكان (r93):</b> النافذة تبدأ بـ<b>رابط Google Maps</b> — الصق ما شاركته الخرائط (أو اضغط 📋 Paste) فيُملأ الاسم والحي؛ ثم <b>Plus code</b> (من تحت العنوان في الخرائط: دبوس دقيق، والحي يُقرأ منه)، ثم الاسم، ثم التصنيف مع <i>Fine dining · ⭐ Top place · Outside the city</i>. <b>Outside the city</b> يسِم بلدة مجاورة مضمومة تحت هذه المدينة؛ وحين يكون في المدينة بلدات يظهر صف <b>Places outside …: Estepona · N</b> فوق التصنيفات — اضغط البلدة لعرض أماكنها وحدها (قائمةً وخريطة)، واضغطها ثانيةً للمدينة كلها؛ وشريحة البلدة على البطاقة تفتحه أيضًا. <b>⚙</b> آخر الصف يدير المدينة: <i>Merge into another city</i> · <i>Split out a town</i> · نقل مكان واحد من Edit · <i>🗑 بجانب البلدة</i> (r97: يحذف البلدة المضمومة بأماكنها وتبقى بقية المدينة) · <i>Undo</i>. <b>المكرَّر (r97):</b> الأماكن التي لديك مرتين صفٌّ مطوي <i>▸ Duplicates · N</i> في الصندوق فوق القائمة — <i>Same Google place</i> أو <i>Same spot</i>؛ اضغط الاسم لفتح بطاقته ثم <i>Keep this</i> على ما تُبقيه (والبقية تُدمج فيه؛ وUndo على الصف). <b>موقع واحد مكان واحد (r96):</b> حفظ مكان أو تثبيته في موقع لديك أصلًا يسأل <i>Keep both · Keep mine · Replace mine</i>؛ وفي الدفعة تُحجز هذه الصفوف مع <i>Keep both · Drop this row</i>. <b>الحي (r96):</b> يُقرأ من الدبوس بقاعدة واحدة لكل المسارات (باريس → 7e arr. · فيينا → المقاطعة · القرية قبل النجع، ولا المدينة ولا الكانتون أبدًا)؛ وبعد هذا التحديث يظهر مرة واحدة شريط <i>Re-read N pins</i> يحدّث أحياء ما لديك. ومع شريحة بلدة مفعّلة يعرض الصندوق فوق القائمة (بلا تصنيف / تصنيف قديم) تلك البلدة وحدها، والشريحة تقول كم منها في الصندوق. وحين تملك المدينة ثلاثة أماكن فأكثر ولا خطة يوم فيها يظهر سطر واحد فوق My places يدعوك لتخطيط يوم، ويختفي بأول خطة (r101-ب). الرمز القصير (ستة أحرف) لا يكون دقيقًا إلا قرب بلدته، لذلك يُفكّ حول مرجع: اسم البلدة الذي ينسخه Google مع الرمز (8FR9+2V Interlaken)، وإلا البلدة إن كان المكان موسومًا Outside the city، وإلا هذه المدينة. وإن وقع الناتج أبعد من ٤٠ كم عن مرجعه لا يُحفظ شيء وتطلب الرسالة الرمز مع اسم بلدته أو الرمز الكامل؛ هذا يصيد المرجع الخطأ حين يبعد المرشَّحان معًا فقط، فأبقِ اسم البلدة مع الرمز للمكان البعيد دائمًا (r102-أ). الخطط اليومية المحفوظة لهذه المدينة تظهر شرائح تحت صف الأزرار تفتح مباشرة (r102-د). <b>وتتبع القائمة</b> (r103): القائمة العامة خططها عامة معها، والمشارَكة بالاسم خططها مشارَكة مع الأشخاص أنفسهم — بلا مفتاح؛ المشاهد يراها شرائح في صفحة مدينتك ويفتحها للقراءة: المحطات بترتيبها والفرعي والملاحظة والمسافات؛ ولا يعرض له التطبيق نقطة انطلاقك ولا أوقاتك ولا دقائق الأرجل (هذه الحقول تبقى داخل مستند الخطة كأي رحلة عامة). المسودة لا تخرج أبدًا؛ الخطة تتبع القائمة عند حفظها. خطط اليوم لا تظهر في خلاصات الرحلات، وحذف المدينة أو دمجها يعيد خططها خاصة. العام والمشارَك من الداخل (r104): قائمة المدينة مستند فهرس ومستند لكل فرعي، وكل فرعي يحمل علامة العام/المشارَك بنفسه، فلا يقرأ المشاهد إلا الفرعيات التي تحملها. ضغط 🌐 أو المشاركة بالاسم يختم الآن كل الفرعيات في الكتابة نفسها، وفتحك قائمتك مرة يصلح أي فرعي خرجت علامته عن الأم (يظهر في التشخيص <i>visibility repaired</i>). والمشاهد الذي يفتح قائمة تقول إن فيها أماكن ولا يقرأ شيئًا يرى <i>Couldn\'t read this list\'s places</i> لا <i>No active places</i>. <b>الأسماء والدبابيس (r107)</b>: الرمز القصير (PXCR+2C New York) يُقرأ حول البلدة التي يسمّيها. الاسم يُطابَق باسم المدينة الأصلي أولًا، والاسم الجانبي الذي لا تحمله إلا بلدة بعيدة لا يُصدَّق وحده: عند اللبس تُسأل <i>Which …?</i> أو <i>Where is …?</i> بدل دبوس في غير موضعه. والدبوس الذي سيقع بعيدًا عن المدينة لا يُحفظ صامتًا: <i>That pin is … km from …</i> تعيدك لتصحيحه أو تحفظه خارج المدينة. <b>⚙ City › Far pins</b> تعرض الدبابيس المحفوظة بعيدًا عن المدينة بلا وسم outside، وأين يقع الرمز نفسه قرب المدينة، وتنقلها (واحدًا أو الكل) مع تراجع. <b>Not fully visible yet (r109)</b>: نقطة على 🌐 تعني أن بعض تصنيفات القائمة ما زالت تحمل علم عام/مشارَك يخالف القائمة نفسها (إصلاح لم يُكتب: بلا اتصال، أو رُفض، أو الحساب موقوف). اضغط 🌐 فيعيد التطبيق محاولة الإصلاح، ولا يبدّل العام ما دامت النقطة. وحفظ القائمة كاملة (أو تبديل العام أو المشاركة) يكتب العلم على كل تصنيف فيطفئ النقطة أيضًا. وفي التشخيص سطر واحد لكل حدث رؤية: <i>VIS · city · public|private · shared N · ما حدث</i>. <b>قراءات المجتمع (r109)</b>: السوق يُقرأ مرة ويبقى للزيارة — العودة وتبديل التبويب والرجوع خلال عشر دقائق بلا قراءة؛ السطر تحت المرشّحات يقول متى قُرئ، و↻ يقرؤه الآن. وما تفعله أنت — نشر أو إخفاء، تمييز، حفظ، نسخ — يُقرأ من الخادم بعده مباشرة فلا ينتظر تغييرك؛ أما عدّاد المشاهدات وتغييرات الآخرين فتصل مع القراءة التالية. <b>تحقق عند الفتح (r109)</b>: الرحلة أو القائمة المحفوظة في الذاكرة تُتحقق بقراءة واحدة كلما فتحتها — إن جعلها صاحبها خاصة أو ألغى مشاركتها أو أُوقف حسابه اختفت فورًا (<i>This list is no longer available</i>). وإيقاف الحساب يُخفي كل قائمة وكل تصنيف تحتها وكل رحلة، ورفعه يعيد كل واحدة كما كانت.' },
      { id: 'trips', h: 'الرحلات', b: 'ابنِ الرحلة بخطوتين: المدينة والأيام والأماكن التي تختارها — واختياريًّا الوصول والمغادرة ومكان الإقامة وما تركبه حين يبعد المكان عن المشي — ثم يرسم MyPickz كل يوم بأربع فترات: صباح · ظهيرة · عصر · مساء، مع بدائل حين تتعدد أماكن الصنف نفسه، وصينية «بلا يوم بعد» لما لم يتسع له البرنامج. انقل ما شئت، وبدّل بين هادئ ومتوازن ومكثّف، وتراجع، ثم اعتمد. تفضّل الترتيب بنفسك؟ «Arrange it myself» يبقي كل الأماكن في الصينية وتسألك الشبكة عن كلٍّ بدوره، و«Auto-fill the rest» يضع ما بقي. السهمان ▲ ▼ بجوار رقم المحطة يرتّبانها داخل فترتها؛ وحين تنقل إلى فترة أخرى فيها محطات تختار موضعه في الترتيب؛ و«Add again…» يضيف زيارة ثانية للمكان نفسه (r105: الاسم نفسه في المسارين). اضغط «رحلة» على أي بطاقة مكان فيهبط في خانته الأنسب — أو في الصينية. <b>مسار اليوم</b>: افتح رحلة معتمدة واختر يومًا وحدّد متى تخرج ومتى تريد العودة؛ كل رِجل تعرض مسافتها التقريبية ووسيلتها (مشي · مترو ومواصلات · سيارة — الافتراض من المسافة)، و«ملاحة» يفتح تطبيقك بالوضع نفسه. اكتب الدقائق التي يعرضها تطبيقك — MyPickz لا يقدّرها أبدًا — فتتبعها أوقات اليوم؛ رِجل بلا دقائق تُبقي اليوم «غير مكتمل»، والعودة بعد الموعد تُعلَّم.<br><b>خطة اليوم — مسار واحد بفرق واحد</b> (r106): خطة يوم واحد تعيش في الأماكن لا في My trips. المساران يشتركان في كل شيء — بابا إضافة المحطات، Start from ورِجل العودة، Options، Add again، وسائل الأرجل، بطاقة المكان، وDay route نفسه بعد الحفظ — ويختلفان في شيء واحد تختاره في الشاشة الأولى: <b>من يرتّب المحطات</b>. <b>In the city</b>: MyPickz بالفترات (صباح · ظهر · عصر · مساء، مع Options حين يتشابه مكانان) أو <i>My order</i>. <b>Day trip</b>: <i>My order</i> (ترتيب إضافتك، ▲ ▼) أو <i>Nearest first</i> من نقطة الانطلاق (كل محطة تُضاف تحطّ في أقرب موضع؛ حرّك واحدة بيدك فيعود الترتيب لك). النوعان بالتفصيل — <b>In the city</b> (أماكنك بالإيقاع المعتاد) و<b>Day trip</b> (مسار خطّي خارج المدينة: قرى · قمم · بحيرات · محطات — محطات تكتبها أو تختارها من My places، ولكل رِجل وسيلتها: قطار · مركب · تلفريك · قطار جبلي · باص · مشي · سيارة — وملاحظة، ومحطة اختيارية، ووقت مثبَّت). سمِّها بـ<b>Trip name</b>، وافتحها من <i>Day plan ▸ Saved</i>، و<b>⧉ Copy into a trip</b> ينسخ اليوم إلى إحدى رحلاتك يومًا جديدًا أو بدل يوم، مع Undo. في المنتقي أماكن <b>Stay</b> و<b>Transportation</b> تُختار كغيرها (منتجع فيه مقهى أو غولف، محطة، موقف: ٦٠ و١٥ دقيقة افتراضًا) (r102-ب). في الخطة المحفوظة الضغط على اسم المحطة يفتح بطاقة المكان — الفرعي والحي والملاحظة وGoogle Maps — والسطر تحت الاسم يعرض الفرعي والحي؛ ودبوس المحطة يتبع دبوس المكان الحالي في قائمتك فيصحّح تصحيحُه المسافات (r102-ج). <b>بابان لإضافة المحطات</b> (r101-ب): «Add from My places» (أماكنك المحفوظة هنا وفي المدن القريبة، بفرعيّها وملاحظتها) و«Add a place not in My places» (تكتبه أو من رابط خرائط — يبقى داخل هذا اليوم)؛ زر «Save this day» يُضاء مع أول محطة ولا يُكتب شيء قبل محطة أو اسم. <b>المدن القريبة</b> (r101-أ): حين تختار من My places يظهر صف شرائح بمدنك الأخرى التي تبعد نحو ساعة ونصف قيادة في اتجاه واحد أو أقل — «+ Gstaad · ~1 h»؛ اضغط إحداها فتنضم أماكنها إلى القائمة تحت اسمها، ويحتفظ كل مكان مختار بمدينته. الزمن تقدير من المسافة المستقيمة لا من طريق فعلي. في المسارين (r105): مكان ليس في My places يُضاف داخل مدينة خطة اليوم من شريحة ✎ Not in My places بجوار ＋ Places فيحطّ في «No day yet» وتسأله ورقة Move عن موضعه · Options في Day route بعد الحفظ: المحطة التي لها بدائل تعرض Option 1 ✓ وOption 2…، والضغط يجعل البديل المحطة الفعلية وتُحسب الأرجل عليه، لكن الدقائق التي كتبتها للخيار القديم لا تنتقل فأعد إدخالها · Add again: المكان نفسه مرة أخرى (داخل المدينة من ورقة Move، وفي رحلة اليوم من شرائح المحطة في آخر المسار) · Start from في خطة اليوم: النقل أولًا ثم الإقامة ثم البقية، وغير المثبَّت معطَّل بسببه (وفي «Where you stay» للرحلة متعددة الأيام كذلك) · المشاهد يرى وسيلة كل رِجل كما اخترتها مع ملاحظتها ويفتح بطاقة المكان من اسم المحطة. <b>شكلان لليوم (r107)</b>: يوم داخل المدينة بفتراته، ويوم رحلة اليوم بمحطاته على <i>your order</i>. كل خطوة تعرف الشكلين: Setup ثم Done يُبقي محطات رحلة اليوم ونقطة انطلاقها وترتيبها · <i>Trip</i> على بطاقة مكان يضيفه آخر محطة في رحلة اليوم ويقول ذلك · خطة اليوم المنسوخة إلى رحلة أطول تحتفظ بيومها عند تغيير الأيام أو الإيقاع وتُفتح بمحرّر المحطات نفسه (شرائح الأيام أعلاه وMove على كل محطة)، وورقة النقل تعرضها خلية واحدة عريضة · اليوم الذي أُفرغ يعود بـ<i>Make it an in-city day</i> · نسخ <i>Add again</i> وتنبيهاتك تبقى بعد إعادة البناء. وإن كادت خطوة تُسقط مكانًا أو تعيد رسم يوم بلا سؤال فلا يُحفظ شيء، وتعود الخطة كما حفظتها آخر مرة، وتظهر ورقة <i>Kept as it was</i>. <b>التحرير جلسة (r108)</b>: لا شيء يُكتب وأنت تحرّر. الخطة التي لم تُعتمد بعد تنتهي بـ<i>Cancel · Save as draft · Approve</i>، والمعتمدة بـ<i>Cancel · Done</i>. الخروج بتعديلات يسأل <i>Discard your changes?</i> وإن تخلّيت عادت الخطة كما كانت تمامًا. وإن أُغلق التطبيق في المنتصف بقي تحريرك على هذا الجهاز وحده، ويسألك عند الزيارة التالية <i>Restore your unsaved edit?</i>. للإضافة باب واحد: <i>＋ Add places</i> — علّم أماكن من My places والمدن القريبة، أو افتح <i>A place not in My places</i> من داخله — ثم يقول إشعار أين حلّ كل مكان (الفترة، أو بديل، أو رقم المحطة، أو <i>No day yet</i>). و<i>Setup</i> خطوة داخل الجلسة (<i>Apply</i> يعيدك إلى الخطة)، وللرحلة المحفوظة مدخل واحد: <i>✏️ Edit</i>. والحارس داخل الجلسة لا يضيّع عملك: الحفظ الذي كان سيُسقط مكانًا لم تحذفه يُرفض بورقة <i>Not saved</i> ويبقى التحرير مفتوحًا. وما تفعله خارج المحرّر يبقى فوريًّا: <i>Trip</i> على بطاقة المكان، ونسخ خطة يوم، والتراجع عن آخرها.' },
      { id: 'curators', h: 'المنتقون', b: 'عالم المنتقي مساحة عرض لمفضلاته فوق قوائمه العادية: بطاقات بعناوينه — أفضل وقت · ماذا تطلب · أين تجلس — وبطاقة مدينة يحدّثها، وآخر التجارب. تابع منتقيًا ليصلك جديده أولًا. تصفّح أماكنه ورحلاته كما يراها — للعرض فقط. المنتقون يُدعون من MyPickz أو يطلبون من حسابهم؛ الشارة مساحة لا تقييم.' },
      { id: 'community', h: 'المجتمع', b: 'قوائم المستخدمين الآخرين ورحلاتهم العامة بالمدينة — ومن حفظ ماذا. صفِّ بالتصنيف والفرعي؛ افتح قائمة واحفظ مكانًا إلى قائمتك — يحتفظ بمصدره. قائمتك خاصة حتى تجعلها عامة؛ والمشاركة بالاسم مع شخص تبقى بينكما.' },
      { id: 'addresses', h: 'العناوين', b: 'البيت والعمل والأهل والأصدقاء والعيادات — دفترك الخاص. أنت وحدك تقرأه؛ لا شيء منه يظهر بالقوائم أو الرحلات أو المجتمع. الصق من الخرائط أو اكتب عنوانًا.' },
      { id: 'cards', h: 'البطاقات والمشاركة', b: 'أي مكان أو قائمة أو رحلة أو بطاقة منتقٍ تُصدَّر صورةً بهوية التطبيق — عربية أو إنجليزية — برمز QR يفتحها في MyPickz. القوائم الطويلة تنقسم بطاقات. أرسلها حيث شئت؛ من يفتحها يحفظ ما يحب.' },
      { id: 'import', h: 'الاستيراد', b: '<b>استيراد قوائمك من خرائط جوجل</b><br>١. افتح <b>takeout.google.com</b> بحساب جوجل الذي تستعمله في الخرائط ← <i>Deselect all</i> ← اختر <b>بندين</b>: <b>Saved</b> (قوائمك) و<b>Maps (your places)</b> ← <i>Next step</i> ← <i>Create export</i>.<br>٢. يرسل لك جوجل بريد «Your Google data is ready» (دقائق إلى ساعات) ← <i>Download your files</i> ← يُحفظ الملف المضغوط في Files ← Downloads (iPhone) أو Downloads (Android).<br>٣. هنا: ☰ ← Import ← اختر الملف المضغوط (لا حاجة لفكّه).<br>٤. تُفرز أماكنك على المدن <b>في جهازك</b> — لا يُرفع شيء ولا يُقرأ شيء من جوجل. تراها شجرةً: دولة ← مدينة ← بلدات أصغر، وتقرر بضغطة أتبقى البلدة الصغيرة مدينةً بذاتها أم تدخل تحت المدينة الكبيرة المجاورة (حيًّا فيها). المدينة الجديدة بمكان أو مكانين تُضمّ افتراضيًّا تحت المدينة المجاورة إن كانت ضمن ٢٠ كم (الصف يقولها مع undo)، وإلا تُترك بلا ✓ لقرارك؛ والبلدة التي حفظتها كمكان («Bled» · «Biarritz») تُعدّ وجهةً ولا تُستورد إلا بطلبك. أخبرنا مرة عمّا تدور حوله كل قائمة (اختياري).<br>٥. افتح مدينة ← الصندوق فوق القائمة يعرض <b>N not pinned yet ›</b> حتى يُثبَّت كل مكان (r98b: سطرا الحالة زالا — عدد الملف في ⓘ Diag): كل ما في ملفك صار في قائمتك برابطه في Google؛ والدبوس يلزم فقط لوضع المكان في مسار يوم أو رؤيته على خريطتك. يبحث MyPickz عن كل مكان في بيانات خرائطنا (بالاسم — حتى لو كان رابط قائمتك يشير إلى بُعد كيلومترات) ويفرزه إلى تصنيفه. ثم ثلاث خطوات: <b>1 · Pin the matches</b> — ضغطة واحدة لـ<b>Strong</b> (اسم تامّ) و<b>Likely</b> (راجع الاسمين ↔؛ 🗑 على القديم أو غير المهم، مع Undo). <b>2 · Pick the right name</b> — للمكان ذي الأشباه اضغط الاسم الصحيح (كلٌّ بعنوانه). <b>3 · Pin from Google Maps</b> — للباقي اضغط <b>Pin</b> على البطاقة: افتح المكان في Google Maps، اسحب بطاقته للأعلى، وتحت العنوان اضغط <b>Plus code</b> (شكله <b>GV74+C3 London</b> — تظهر Copied)، ارجع واضغط <b>Paste</b>: دبوس واحد دقيق يُفكّ على جهازك بلا أي طلب لـGoogle. وكل بطاقة مثبَّتة تعرض رمزها تحت العنوان، فالتحقق مقارنة سطرين: رمز واحد = موضع واحد. أو أبقِه في قائمتك بلا دبوس (<b>Not pinned yet</b> يعرضها ويحفظها ملفًا). وما لا يُعرف يبقى في الصندوق لك — ومنه الأماكن خارج ضوابط المحتوى (بارات · سهر · كحول · معسل · قمار) تُوسم ولا تُفرز أبدًا.<br>٦. غيّرت رأيك؟ <b>Undo last import</b> — في ⚙ City (<i>Pins &amp; import</i>) أو ☰ ← Import — يزيل ما أضافه الاستيراد ويُبقي كل ما عملت عليه — ما ثبّته أو عدّلته أو نقلته أو وضعته في رحلة. واختيار الملف نفسه لاحقًا يطبّق قراراتك ويتخطّى ما أزلته بيدك. و<b>Receipt</b> إيصال بما دخل. وإن أُغلق التطبيق في المنتصف فـ<b>Resume</b> يكمل المدن الباقية.<br><b>ماذا يحدث لكل مكان</b><br>· <b>موجود عندك</b> ← يُتخطّى ولا يتغير شيء. <b>اسمه اسم مكان قديم عندك</b> (صف واحد ومكان واحد) ← لا توأم: القديم يكسب معرّف الخريطة والرابط الطويل ويحتفظ بدبوسه. <b>يشبه مكانًا عندك</b> ← يبقى موسومًا لتقرر أنت.<br>· <b>في مدينة ليست عندك بعد</b> ← تُنشأ لك المدينة.<br>· <b>في مدينة لا نغطيها بعد</b> ← يُعدّ ويبقى خارجًا؛ وإن عُرفت دولته <b>ينتظر</b> (الاسم والرابط فقط، بلا موقع) حتى تضيف مدينة منها — ثم «Place them now» يُدخله.<br><b>الخصوصية:</b> ملف Takeout يُقرأ في جهازك فقط ولا يُرسل. كل مكان يحتفظ بموقعه من الملف في رابطه لنطابقه على خريطتنا؛ والدبوس من بيانات خريطتنا فقط لا من الملف.<br><b>بعد الاستيراد:</b> ⚙ في صفّ الأماكن — <i>Merge into another city</i> (أماكنها تبقى بتصنيفاتها موسومة بلدةً خارج المدينة الأكبر) · <i>Split out a town</i> (مدينة جديدة من معجمنا أو من دبابيسها) · نقل مكان واحد من Edit · <i>🗑 بجانب البلدة</i> (r97: حذف بلدة مضمومة بأماكنها) · <i>Undo</i> · وتحت <i>Pins &amp; import</i> (r98b) <i>Re-read areas from pins</i> و<i>Undo last import</i> — ولوحة Pins فوق الخريطة تظهر ما دام شيء ينتظر التثبيت فقط. والمكان نفسه مرتين يظهر صفًّا <i>▸ Duplicates · N</i> في الصندوق فوق القائمة (r97) — اضغط الاسم لبطاقته وأبقِ واحدًا والبقية تُدمج فيه. وفي الدفعة يُحجز الصف الذي في موقع لديك أصلًا — <i>Keep both</i> أو <i>Drop this row</i>.' },
      { id: 'privacy', h: 'بياناتك وخصوصيتك', b: 'أماكنك ملكك: نزّل كل بياناتك بملف مفتوح متى شئت، واستوردها، واحذف حسابك بكل أثره. الموقع يُستعمل عند ضغطك «Nearby» فقط ولا يُخزَّن. المتابعة معلنة لمن تتابعه. نستعمل بيانات خرائط مفتوحة بنسبتها. من رابط خرائط جوجل نقرأ اسم المكان وعنوانه فقط لنجده في بياناتنا — لا إحداثياته أبدًا؛ الرابط يبقى الباب. والمكان المحفوظ بلا رابط يُفتح بحثًا في خرائط جوجل باسمه وحيّه ومدينته ودولته. وملف Takeout يُقرأ في جهازك فقط ولا يُرسل؛ كل مكان يحتفظ بموقعه من الملف في رابطه للمطابقة، والدبوس من بيانات خريطتنا فقط. MyPickz ليس تابعًا لجوجل.' },
      { id: 'howto', h: 'كيف تنسخ رابطًا وتصدّر قوائمك', b: '<b>رابط المكان:</b> افتح المكان بخرائط جوجل ← مشاركة ← نسخ ← بالتطبيق: ＋ Add place ← Paste from Maps.<br><b>قوائمك المحفوظة:</b> Google Takeout ← Deselect all ← اختر «Saved» و«Maps (your places)» ← Create export ← نزّل الملف المضغوط من بريد جوجل ← بالتطبيق: ☰ ← Import.<br><b>على أندرويد:</b> من خرائط جوجل، مشاركة ← MyPickz مباشرة <span class="soon-tag">قريبًا</span>.' },
      { id: 'settings', h: 'الإعدادات', b: 'الشاشة الرئيسية (تلقائي أو اختيارك) · مدني · لغة التصدير · الحساب.' },
      { id: 'home', h: 'إضافة MyPickz إلى سطح المكتب سواء في جهاز الجوال أو الكمبيوتر', b: '1. افتح الموقع من المتصفح (Safari أو غيره)<br>2. اضغط زر المشاركة (Share) على الجوال، أو قائمة الخيارات على الكمبيوتر<br>3. اختر "Add to Home Screen" (جوال) أو "Create Shortcut" (كمبيوتر)<br>4. الآن يمكنك فتح MyPickz بضغطة واحدة، تمامًا كأي تطبيق آخر' }
    ]
  }
};


function setHelpLang(lang){ /* ب-٢-٢-أ٢ (v3 · ١٤): مبدّل اللغة شريحتان مقطعيتان تحت رأس القشرة */
  helpLang = lang;
  document.getElementById('helpLangArBtn').classList.toggle('on', lang === 'ar');
  document.getElementById('helpLangEnBtn').classList.toggle('on', lang === 'en');
  renderHelpModal();
}

function toggleHelpSection(i){
  helpOpenIndex = (helpOpenIndex === i) ? -1 : i;
  renderHelpModal();
}

function renderHelpModal(){
  const data = HELP_CONTENT[helpLang];
  const dir = helpLang === 'ar' ? 'rtl' : 'ltr'; const al = helpLang === 'ar' ? 'right' : 'left';
  document.getElementById('helpTitle').textContent = data.title;
  const wrap = document.getElementById('helpSections');
  wrap.style.direction = dir; wrap.style.textAlign = al;
  const it = data.intro;
  let h = '<div class="help-l1" style="font-size:13px; line-height:1.75;">'
    + '<p style="margin:0 0 8px;">' + it.def + '</p>'
    + '<p class="help-feats" style="margin:0 0 10px; font-size:11.5px; font-weight:700; color:var(--saffron);">' + it.feats + '</p>'
    + '<ul style="margin:0 0 10px; padding-inline-start:18px;">' + it.dests.map(function(d){ return '<li style="margin:2px 0;"><b>' + d[0] + '</b> — ' + d[1] + '</li>'; }).join('') + '</ul>'
    + '<p style="margin:0 0 8px;">' + it.everywhere + '</p>'
    + '<p style="margin:0 0 10px;">' + it.start + '</p></div>'
    + '<button type="button" class="btn btn-ghost" style="margin:0 0 10px; padding:7px 14px; font-size:12px;" onclick="helpExpanded = !helpExpanded; renderHelpModal();">' + (helpExpanded ? data.readLess + ' <span class="arr">⌃</span>' : data.readMore + ' <span class="arr">⌄</span>') + '</button>';
  if (helpExpanded){
    h += data.sections.map((sec, i) => `
    <div style="border:1px solid var(--line); border-radius:10px; margin-bottom:8px; overflow:hidden; background:var(--ivory-bright);" id="help_sec_${sec.id}">
      <button type="button" onclick="toggleHelpSection(${i})" style="width:100%; text-align:${al}; background:var(--ivory-bright); border:none; padding:11px 14px; font-family:'Cairo',sans-serif; font-weight:700; font-size:13px; color:var(--ink); display:flex; justify-content:space-between; align-items:center; cursor:pointer;">
        <span>${sec.h}</span><span style="font-size:11px; color:var(--brass);">${helpOpenIndex===i ? '▲' : '▼'}</span>
      </button>
      ${helpOpenIndex===i ? `<div style="padding:12px 14px; font-size:12.5px; line-height:1.9; color:var(--ink);">${sec.b}${sec.id === 'privacy' ? '<div class="help-counters">' + escapeHtml(mpTripCountersLine()) + '<br>' + escapeHtml(tkImportLine()) + ' <button type="button" class="actn" onclick="mpTripCountersReset()">Reset</button></div>' : ''}</div>` : ''}
    </div>`).join('');
  }
  wrap.innerHTML = h;
  wrap.innerHTML += '<div class="chipgrid c3" style="margin-top:6px;"><button type="button" class="pl-src" onclick="closeHelpModal(); copyLink();">🔗 Copy link</button><button type="button" class="pl-src" onclick="closeHelpModal(); showQR();">🀄 QR</button><a class="pl-src" href="mailto:mypickz.app@gmail.com?subject=MyPickz%20Feedback">✉️ Contact us</a></div>'; // ر٧٢-أ-١: «Share the app» داخل Help (المرجع §٧)
  const cb = document.getElementById('helpCloseBtn'); cb.textContent = currentUser ? data.closeLabel : data.gotIt; // أ-١٢-٢: للزائر «Got it — sign in»
}
function openSymbols(){ /* r87-2 (كلمة المالك ١٢:٥٥ · ١٣:٠٤): ما معنى كل زر وكل حالة — ظاهرة في الشريط العلوي */
  const bd = document.getElementById('dashBackdrop'); if (!bd) return; bd.classList.add('show'); if (typeof dashSet === 'function') dashSet('Symbols', null); const body = document.getElementById('dashBody'); if (!body) return;
  const row = function(ic, name, what){ return '<div style="display:flex; gap:10px; align-items:flex-start; padding:7px 0; border-bottom:1px solid var(--line-night);"><span class="sym-ico">' + (ic.indexOf('<') === 0 ? ic : mpIcon(ic, { size: 18 })) + '</span><span style="flex:1; min-width:0; font-size:13px; line-height:1.45;"><b>' + name + '</b><br><span class="dim" style="font-size:12px;">' + what + '</span></span></div>'; };
  body.innerHTML = '<div id="mpSymbols"><div class="dim" style="font-size:12px; margin-bottom:6px;">The buttons on every place card</div>'
    + row('maps', 'Google Maps', 'Opens this place in Google Maps — your saved link, exactly as you had it.')
    + row('map', 'On map', 'This place is pinned: shows it on your MyPickz map (the one used for day plans and Nearby).')
    + row('pin', 'Pin', 'Not pinned yet. Opens “Pin from Google Maps”: accept a match we found, or paste the Plus code from under the address in Google Maps — one exact pin.')
    + row('bookmark', 'Bookmark', 'Keeps the place in your bookmarks across cities.')
    + row('trip', 'Trip', 'Adds the place to a trip (it needs a pin to be routed in a day plan).')
    + row('share', 'Share', 'Shares the place with someone.')
    + row('edit', 'Edit', 'Name, category, link, area, picks, note — and the Plus code field.')
    + row('top', 'Top', 'Marks it as one of your top places.')
    + '<div class="dim" style="font-size:12px; margin:12px 0 6px;">The two states of a place</div>'
    + row('<b style="font-size:12px;">✓</b>', 'Pinned', 'It has a spot on your MyPickz map — from your Takeout file, from a match in our map data you accepted, from someone who pinned the same place before, or from your own Plus code / map tap. Its Plus code shows under the address (More).')
    + row('<span class="lencount over" style="display:inline;">118 / 120 characters</span>', 'Character limit', 'Shows under a text field as you near its limit; over the limit, Save asks you to shorten (r100-ج)')
    + row('<b class="unsaved" style="font-size:12px;">Unsaved</b>', 'Not saved yet', 'A change that could not be saved (r100-أ): the sheet offered Retry or Discard and you kept it on screen. Save again when you are online, or Discard it — nothing is lost on the server.')
    + row('<b style="font-size:12px;">·</b>', 'Not pinned yet', 'It is on your list with its Google link, but has no spot on your map yet. Nothing is pinned without your tap. A pin matters only for day plans, Nearby and the map.')
    + '<div class="dim" style="font-size:12px; margin:12px 0 6px;">Where things live</div><div style="font-size:13px; line-height:1.5;"><b>List</b> — your places by category; the box above it holds what still needs a category or a pin (r98b: no status lines under My places).<br><b>Map</b> — your pins; the Pins panel (suggested pins to accept, look-alikes to pick, not pinned yet) shows only while something is left to pin.</div>'
    + '<div class="dim" style="font-size:12px; margin:12px 0 6px;">The row under your places</div>' /* r93 (ملاحظة المالك ٢٩ أكتوبر ١٤:٤٥) */
    + row('<b style="font-size:15px;">🗓</b>', 'Day plan', 'One path, one difference (r106): In the city or a Day trip — same doors, same Day route; you only choose who orders the stops (MyPickz by periods · My order · Nearest first). A one-day plan that lives here in Places. Saved plans show as chips under this row (🏙 in the city · 🚞 day trip · draft) and open with one tap (r102-د); ⧉ Copy into a trip copies the day into one of your trips. Plans follow the list: public with a public list, shared with a shared one; viewers see stops only (r103).')
    + row('<b style="font-size:12px;">📍 / ✎</b>', 'Add a stop', 'Both paths (r105): Add from My places (saved places here and nearby, with category and note) · Add a place not in My places (typed or from a Maps link; kept inside this plan). Day trip: two doors, Save this day off until the first stop (r101-ب). In the city: the ✎ Not in My places chip next to ＋ Places; the new stop lands in No day yet and the Move sheet asks where.')
    + row('<b style="font-size:11px;">Option 2</b>', 'Options', 'In Day route after saving: a stop that has alternatives shows Option 1 (the stop, ✓) and Option 2… — tap an option to make it the real stop; the legs are recomputed for it (minutes you typed for the old option are not carried), the other becomes an alternative. Viewers see the options read-only (r105).')
    + row('<b style="font-size:11px;">Add again</b>', 'Add again', 'The same place once more — in the city from the Move sheet (Add again… asks the day and period), in a day trip from the stop chips (a copy at the end of the route, move it with ▲▼). Parking first and last is usually Start from + the return leg instead (r105).')
    + row('<b style="font-size:12px;">🗓 →</b>', 'Plan a day', 'One line above My places when the city has 3+ places and no day plan yet — tap it to open Day plan; gone after the first plan (r101-ب).')
    + row('<b style="font-size:12px;">+ 1 h</b>', 'Nearby city', 'In the places picker (From My places): one of your other cities within about 1 h 30 by car one way — tap it and its places join the list under its name (r101-أ). The time is a straight-line estimate.')
    + row('<b style="font-size:15px;">📍</b>', 'Nearby', 'This city\'s places by straight-line distance from where you are, with a Go button in your navigation app.')
    + row('<b style="font-size:15px;">📤</b>', 'Export', 'Preview and send this list — as a card, a file or text.')
    + row('<b style="font-size:15px;">🌐</b>', 'Public', 'Lit when this city list is public for the community; tap to switch.')
    + row('<b style="font-size:15px;">🌐<sup style="color:var(--saffron);">●</sup></b>', 'Not fully visible yet', 'r109 · a dot on 🌐: some sub-categories of this list still carry a different public/shared mark than the list (a repair could not be written). Tap 🌐 to try the repair again — it does not switch public while the dot is there.')
    + row('<b style="font-size:14px;">↻</b>', 'Read … ago · ↻', 'r109 · Community: the market is read once and kept for ten minutes; the line says when, ↻ reads it again now.')
    + row('<b style="font-size:15px;">👤+</b>', 'Share', 'Share this city list with someone by name.')
    + row('<b style="font-size:15px;">⚙</b>', 'City', 'Merge into another city · Split out a town ⤴ · 🗑 Remove a town with its places (r97) · move one place from Edit · Undo the last of these · Pins &amp; import (r98b): Re-read areas from pins · ↶ Undo last import.')
    + row('<b style="font-size:13px;">📍</b>', 'Far pins · N', 'r107 · in ⚙ City when pins sit far from the city without the outside mark — usually a short Plus code read around the wrong town. The list shows where the same code lands near the city; Move (one or all) puts them back, Undo stays on the sheet.')
    + row('<b style="font-size:11px;">▸ Dup</b>', 'Duplicates · N', 'r97 · a folded row in the box above the list: places you have twice (Same Google place / Same spot) — tap a name for its card, Keep this on the one to keep; Undo sits on the row.')
    + row('<b style="font-size:12px;">Re-read</b>', 'Areas follow new rules', 'r96 · shown once per city above the list: Re-read N pins refreshes the areas of the pins you already have · Later hides it.')
    + row('<b style="font-size:11px;">same spot</b>', 'Same spot as …', 'r96 · a place at a spot you already have: Keep both · Keep mine · Replace mine; in a batch the row is held — Keep both · Drop this row.')
    + '<div class="dim" style="font-size:12px; margin:12px 0 6px;">Places outside the city</div>'
    + row('<b style="font-size:15px;">🏘</b>', 'Places outside …', 'Appears only when the city has nearby towns kept under it (Outside the city). Tap a town to see its places only, in the list and on the map; tap it again for the whole city.')
    + row('<b style="font-size:12px;">⤴</b>', 'Town chip', 'On a card: “Estepona · outside Málaga” with a chip that opens that town\'s filter.')
    + '<div class="dim" style="font-size:12px; margin:12px 0 6px;">The trip editor</div>' /* r108 */
    + row('<b style="font-size:12px;">Done</b>', 'Cancel · Save as draft · Approve · Done', 'r108 · the trip editor is a session: nothing is written until you press one of these. Not approved yet: Cancel · Save as draft · Approve. Approved: Cancel · Done. Leaving with changes asks Discard your changes?; an edit cut off by the app closing is offered back with Restore your unsaved edit?.')
    + row('<b style="font-size:15px;">＋</b>', '＋ Add places', 'r108 · the one door to add in the trip editor: tick places in My places and nearby cities, or open A place not in My places inside it. A note then says where each one landed.')
    + '</div>'; }
function openHelpFor(tab){ // أ-١٢-٢: زر «؟» يفتح النبذة على قسم الوجهة الحالية
  const map = { Places: 'places', Trips: 'trips', Curators: 'curators', Community: 'community', Addresses: 'addresses' }; const id = map[tab] || null;
  helpExpanded = !!id; helpOpenIndex = id ? HELP_CONTENT[helpLang].sections.findIndex(function(x){ return x.id === id; }) : -1;
  openHelpModal(); if (id){ const el = document.getElementById('help_sec_' + id); if (el && el.scrollIntoView) el.scrollIntoView({ block: 'start' }); }
}
const INTRO_SEEN_KEY = 'mypickz_intro_seen'; // أ-١٢-٢: علم محلي — أول فتح للرابط (الزائر يقرأ النبذة فقط ثم البوابة)
/* و-٢: العلم المحلي في موضعين — localStorage وكعكة mp_intro (سنة · SameSite=Strict · تديرها عملية الشبكة التي لا تُقتل مع الصفحة، كما نجا أثر هـ-٩ حين مُسح localStorage) — فلا يعود الدليل بضياع التخزين المحلي؛ أيٌّ منهما يكفي. الكعكة لهذا العلم وحده (اختيار ٣ بالبيان) */
function introSeenCookie(){ try{ return /(?:^|;\s*)mp_intro=1(?:;|$)/.test(document.cookie); }catch(e){ return false; } }
function introSeenLocally(){ let ls = null; try{ ls = localStorage.getItem(INTRO_SEEN_KEY); }catch(e){ return true; } return ls === '1' || introSeenCookie(); }
function markIntroSeen(){ try{ localStorage.setItem(INTRO_SEEN_KEY, '1'); }catch(e){} try{ document.cookie = 'mp_intro=1; max-age=31536000; path=/; SameSite=Strict' + (location.protocol === 'https:' ? '; Secure' : ''); }catch(e){} }
function openHelpModal(){
  if (helpOpenIndex === -1 && !helpExpanded) helpExpanded = false; // المستوى الأول أولًا
  renderHelpModal();
  document.getElementById('helpLangArBtn').classList.toggle('on', helpLang === 'ar');
  document.getElementById('helpLangEnBtn').classList.toggle('on', helpLang === 'en');
  const bk = document.getElementById('helpBackBtn'); if (bk) bk.classList.toggle('hidden', !window.__mpFromDrawer); /* ب-٢-٢-أ٢: Back يظهر حين تُفتح من الدرج فقط (من «؟» أو أول فتح: ✕ وزر الإغلاق) */
  document.getElementById('helpBackdrop').classList.add('show');
}
function closeHelpModal(){
  document.getElementById('helpBackdrop').classList.remove('show');
  if (!currentUser){ markIntroSeen(); if (!document.getElementById('authBackdrop').classList.contains('show')) openGate(); } // أ-١٢-٢: الزائر: النبذة ثم البوابة
}
// نبذة دليل الاستخدام تُفتح تلقائيًا مرة واحدة: فور إنشاء الحساب الجديد فقط (قرار المالك ١٧ أغسطس).
// كانت تفتح عند تحميل الصفحة لأي مسجَّل مرة بالجهاز (علم محلي) — أثرها العملي: تظهر بعد التحديث لا بعد التسجيل.
function openHelpAfterSignUp(){
  try{ runOnboardingIfNeeded(); }catch(e){}
}

/* r75a (اللوحة ٨ — قرار المالك ١١ أكتوبر): «Icons guide» من الدرج تحت Help — صفحة واحدة على القشرة تجمع رموز التطبيق بأقسامها: أفعال البطاقة · مشاركة القائمة · دبابيس الخريطة · شرائح الحالة · الشارات. تُبنى من الطقم نفسه (mpIcon) فلا تتباعد عن البطاقة */
function iconsGuideHtml(){
  const row = function(icon, name, desc, cls){ return '<div class="ig-row"><span class="ig-ic' + (cls ? ' ' + cls : '') + '">' + icon + '</span><span class="ig-nm">' + name + '</span><span class="ig-ds">' + desc + '</span></div>'; };
  const sec = function(t){ return '<div class="ig-sec">' + t + '</div>'; };
  const fams = ['cafe', 'dish', 'cuisine', 'store', 'product', 'parks', 'squares', 'rest'];
  return '<div class="ig">'
    + sec('Place card actions')
    + row(mpIcon('maps', { size: 18 }), 'Google Maps', 'Opens the place in Google Maps, outside the app')
    + row(mpIcon('map', { size: 18 }) + '<span class="pc-dot ig-dot" aria-hidden="true"></span>', 'On map', 'Shows the place on our map. A saffron dot means it still needs a pin — confirm or move it there')
    + row(mpIcon('bookmark', { size: 18 }), 'Bookmark', 'Keep it in your private Bookmarked list — any place, yours or others’')
    + row(mpIcon('trip', { size: 18 }), 'Trip', 'Add it to one of your trips')
    + row(mpIcon('share', { size: 18 }), 'Share', 'Send this one place as a card or a message')
    + row(mpIcon('save', { size: 18 }), 'Save', 'Copy a place from someone’s list into yours — with credit (Saved ✓ once copied)')
    + row(mpIcon('flag', { size: 18 }), 'Report', 'Flag someone’s place or list to the owner of the app', 'flag')
    + row(mpIcon('phone', { size: 18 }), 'Call', 'Personal addresses only — dials the saved number')
    + row(mpIcon('edit', { size: 18 }), 'Edit', 'Name, area, note, category — and delete')
    + row(mpIcon('top', { size: 18, fill: true }), 'Top', 'Mark it among your top places — shown on your curator page', 'on')
    + sec('Sharing a whole list')
    + row(mpIcon('globe', { size: 18 }), 'Public', 'Your city list is open to everyone in Community')
    + row(mpIcon('personPlus', { size: 18 }), 'Share with', 'Give one person access — appears in their “Shared with you”. Saved groups share with the same people in one tap; a group is yours alone and sharing with it is a snapshot of its members at that moment')
    + sec('Pins on the map')
    + '<div class="ig-pins">' + fams.map(function(f){ return '<span class="ig-pk"><span class="pinkey-' + f + '"><span class="pinkey-dot"></span></span>' + escapeHtml(PIN_FAMILY_LABEL[f] || f) + '</span>'; }).join('')
    + '<span class="ig-pk"><span class="pinkey-dot ig-sugg"></span>Suggested — one match, not confirmed</span><span class="ig-pk"><span class="pinkey-dot ig-prob"></span>Probable — several matches, numbered</span></div>'
    + '<div class="ig-ds" style="padding:2px 0 0;">Confirming, choosing or moving a pin happens on the map — tap On map, then use the pin’s popup.</div>'
    + sec('Badges')
    + row('<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="12" cy="12" r="8"/><path d="m9 12 2 2 4-4"/></svg>', 'Curator', 'Carries the Curator badge — their lists appear under Curators')
    + row('<span style="font-size:10px; font-weight:800;">From</span>', 'From …', 'A copy saved from someone’s list; “From ex-member” when that account is gone')
    + '</div>';
}
function openIconsGuide(){
  const bd = document.getElementById('dashBackdrop'), body = document.getElementById('dashBody'); if (!bd || !body) return;
  dashSet('Icons guide', null); body.innerHTML = iconsGuideHtml(); bd.classList.add('show');
}
